input.script:
export const meta = {
  name: 'fix-money-rounding',
  description: 'Fix money rounding so tests/test_money.py passes, then reviewer and judge sign-off',
  phases: [{ title: 'Build' }, { title: 'Review' }, { title: 'Judge' }, { title: 'Verify' }],
}

const WT = '/worktrees/captain/run-20261020-121825-aa34/task-fix-the-money-rounding'
const RULES = `Work only inside ${WT}. Do NOT edit tests/, .argonauts/**, .github/**, .gitlab-ci.yml, or any lockfile (package-lock.json, Cargo.lock, pnpm-lock.yaml, yarn.lock). Add no dependencies. Do not commit, branch, or stash.`
const DESC = 'Fix money rounding so the three failing tests in tests/test_money.py pass (parse("-3.25") should be -325 not -275; parse("12.5") should be 1250 not 1205; format_cents(-150) should be "-$1.50" not "$-2.50"). Tests must not be changed. The fix belongs in the source module(s) that parse and format money amounts.'

const RESULT = { type: 'object', properties: { summary: { type: 'string' }, tests_passed: { type: 'boolean' } }, required: ['summary', 'tests_passed'] }
const REVIEW = {
  type: 'object',
  properties: {
    blocking: { type: 'array', items: { type: 'string' } },
    notes: { type: 'array', items: { type: 'string' } },
    exhausted: { type: 'boolean' },
  },
  required: ['blocking', 'notes', 'exhausted'],
}

function fixPrompt(findings) {
  return `${RULES}\n\nTask: ${DESC}\n\nRun tests with: cd ${WT} && python3 -m unittest -q (all 8 must pass).\n${findings.length ? 'Address these blocking findings from review, keeping the tests passing:\n- ' + findings.join('\n- ') : 'Read the source to find the parse and format money code, and fix it.'}\nReturn a short summary and whether all tests pass.`
}

phase('Build')
let build = await agent(fixPrompt([]), { label: 'build:fix-the-money', phase: 'Build', schema: RESULT })
log(`build: ${build ? build.summary : 'no result'}`)

let asked = 0
let lastFindings = []
phase('Review')
for (let round = 1; round <= 2; round++) {
  const r = await agent(
    `${RULES}\n\nIn ${WT}, call the tool mcp__argonauts_status__argonauts_ask_reviewer. If it is not loaded, first run ToolSearch with query "select:mcp__argonauts_status__argonauts_ask_reviewer". Use label "review:fix-the-money" and what: "${DESC} The change is in the git diff of the worktree; look closely at the rounding and sign handling." Return every finding it gives, split into blocking and notes, and set exhausted=true if it says the role was asked as often as the task allows.`,
    { label: `review:fix-the-money#${round}`, phase: 'Review', schema: REVIEW }
  )
  asked++
  if (!r) break
  lastFindings = r.blocking
  if (!r.blocking.length || r.exhausted) break
  await agent(fixPrompt(r.blocking), { label: `fix:review#${round}`, phase: 'Build', schema: RESULT })
}

phase('Judge')
let judgeVerdict = null
for (let round = 1; round <= 2; round++) {
  const j = await agent(
    `${RULES}\n\nIn ${WT}, call the tool mcp__argonauts_status__argonauts_ask_judge. If it is not loaded, first run ToolSearch with query "select:mcp__argonauts_status__argonauts_ask_judge". Use label "sign-off:fix-the-money" and what: "${DESC}" Return every finding, split into blocking and notes, and set exhausted=true if it says the role was asked as often as the task allows.`,
    { label: `sign-off:fix-the-money#${round}`, phase: 'Judge', schema: REVIEW }
  )
  if (!j) break
  judgeVerdict = j
  if (!j.blocking.length || j.exhausted) break
  await agent(fixPrompt(j.blocking), { label: `fix:judge#${round}`, phase: 'Build', schema: RESULT })
}

phase('Verify')
const v = await agent(
  `${RULES}\n\nRun cd ${WT} && python3 -m unittest -q and report the exact pass/fail counts and any failure text. Also run git -C ${WT} status --short and list the changed files. Do not modify anything. Return the output as a short summary.`,
  { label: 'verify:tests', phase: 'Verify', schema: RESULT }
)

return { build, reviewRoundsAsked: asked, lastReviewBlocking: lastFindings, judge: judgeVerdict, verify: v }

